<?= $this->extend('layouts/main') ?><?= $this->section('content') ?>
<div class="page-head"><div><p class="eyebrow">Organização</p><h1>Comunidades</h1><p>Estruture o acervo em comunidades e coleções.</p></div><div class="page-head-actions"><?php if ($selectedCommunityId !== ''): ?><a class="button secondary" href="<?= site_url('comunidades/'.$selectedCommunityId.'/colecoes/nova') ?>">Nova coleção</a><?php else: ?><span class="button secondary" aria-disabled="true" title="Selecione uma comunidade para criar uma coleção.">Nova coleção</span><?php endif ?><a class="button" href="<?= site_url('comunidades/nova') ?>">Nova comunidade</a></div></div>
<div class="card-grid community-grid"><?php foreach ($projects as $project): ?><?php $isSelected = $selectedCommunityId === $project['id']; ?><article class="card community-card <?= $isSelected ? 'is-selected' : '' ?>"><div class="community-card-head"><span class="badge"><?= esc($project['code']) ?></span><details class="action-menu"><summary aria-label="Ações de <?= esc($project['name']) ?>">Ações</summary><div class="action-menu-panel"><a href="<?= site_url('comunidades/'.$project['id'].'/trocar-imagem') ?>">Trocar imagem</a><a href="<?= site_url('comunidades/'.$project['id'].'/editar') ?>">Editar dados</a><a href="<?= site_url('comunidades/'.$project['id'].'/permissoes') ?>">Permissões</a><form method="post" action="<?= site_url('comunidades/'.$project['id'].'/visibilidade') ?>"><?= csrf_field() ?><label>Visibilidade<select name="visibility"><option value="public" <?= ($project['visibility'] ?? 'restricted') === 'public' ? 'selected' : '' ?>>Público</option><option value="restricted" <?= ($project['visibility'] ?? 'restricted') === 'restricted' ? 'selected' : '' ?>>Restrito</option><option value="excluded" <?= ($project['visibility'] ?? '') === 'excluded' ? 'selected' : '' ?>>Excluído</option></select></label><button type="submit">Aplicar</button></form><form method="post" action="<?= site_url('comunidades/'.$project['id'].'/excluir') ?>" onsubmit="return confirm('Excluir esta comunidade? O histórico será preservado.')"><?= csrf_field() ?><button class="danger-action" type="submit">Excluir</button></form></div></details></div><?php if (! empty($project['cover_image'])): ?><img class="collection-cover" src="<?= site_url('comunidades/'.$project['id'].'/imagem') . '?v=' . sha1($project['cover_image']) ?>" alt="<?= esc($project['name']) ?>" loading="lazy"><?php endif ?><div><h2><?= esc($project['name']) ?></h2><p><?= esc($project['description'] ?: 'Sem descrição.') ?></p><p class="visibility-label">Visibilidade: <?= esc(['public' => 'Público', 'restricted' => 'Restrito', 'excluded' => 'Excluído'][$project['visibility'] ?? 'restricted']) ?><?= $isSelected ? ' · Selecionada' : '' ?></p></div><form method="post" action="<?= site_url('comunidades/'.$project['id'].'/selecionar') ?>" class="community-select-form"><?= csrf_field() ?><button class="button <?= $isSelected ? 'selected-community' : 'secondary' ?>" type="submit" aria-pressed="<?= $isSelected ? 'true' : 'false' ?>"><?= $isSelected ? 'Comunidade selecionada' : 'Selecionar Comunidade' ?></button></form></article><?php endforeach ?></div>
<?php if (!$projects): ?><div class="empty">Nenhuma comunidade cadastrada.</div><?php endif ?>
<?= $this->endSection() ?>
